const MOVES_BY_ID = Object.freeze(Object.fromEntries(MOVES.map((m) => [m.id, m])));
const MOVES_BY_NAME = Object.freeze(Object.fromEntries(
  MOVES.map((m) => [m.name.toLowerCase(), m])));

function getMoveById(id) {
  return (typeof id === 'string' && MOVES_BY_ID[id]) || null;
}
function getMoveByName(name) {
  if (typeof name !== 'string') return null;
  return MOVES_BY_NAME[name.toLowerCase()] || null;
}
function movesByType(type) {
  return MOVES.filter((m) => m.type === type);
}
function movesByShape(shape) {
  return MOVES.filter((m) => m.shape === shape);
}
function movesByElement(element) {
  return MOVES.filter((m) => m.element === element);
}
function maxUsesFor(move) {
  const pp = move && typeof move.pp === 'number' ? move.pp : 0;
  return Math.max(5, Math.round(pp * 1.5)) * 2;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    MOVE_COUNT, TIMING, SHAPE_RANGE_U, AIM_SHAPES,
    LEGACY_TYPE_TO_ELEMENT, UNMAPPED_TYPES,
    MOVES, MOVES_BY_ID, MOVES_BY_NAME,
    getMoveById, getMoveByName, movesByType, movesByShape, movesByElement,
    maxUsesFor,
  };
}

